-- Solvant Signal Engine — READ-ONLY migration preflight. Safe to run in the Supabase SQL editor or via psql.
-- It changes nothing (runs inside a READ ONLY transaction). GENERATED by supabase/scripts/gen_preflight.py — do not edit.
-- Verdict rows: OK / INFO / WARN / REJECT. Any REJECT means: do NOT apply the migrations.
begin transaction read only;

with expected as (
  select @TABLES@::text[] as tables, @FUNCS@::text[] as funcs, @VIEWS@::text[] as views,
         @TYPES@::text[] as types, @VERSIONS@::text[] as versions
),
schema_state as (
  select exists (select 1 from pg_namespace where nspname = 'solvant') as present
),
ledger as (   -- dynamic read (the table may not exist): evaluated only when it does
  select case when to_regclass('solvant.schema_migrations') is null then '{}'::text[]
              else (select coalesce(array_agg(x::text order by x::text), '{}') from unnest(xpath('//version/text()',
                     query_to_xml('select version from solvant.schema_migrations', false, false, ''))) x) end as versions
),
objs as (
  select c.relname as name, case c.relkind when 'r' then 'table' when 'v' then 'view' when 'm' then 'matview' when 'S' then 'sequence'
         when 'i' then 'index' when 'p' then 'table' when 'f' then 'foreign table' else c.relkind::text end as kind
    from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'solvant'
  union all
  select p.proname, 'function' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'solvant'
  union all
  select t.typname, 'type' from pg_type t join pg_namespace n on n.oid = t.typnamespace
   where n.nspname = 'solvant' and t.typtype in ('e', 'd', 'c') and not exists (select 1 from pg_class c where c.reltype = t.oid)
),
unexpected as (
  select o.kind, o.name from objs o, expected e
   where (o.kind = 'table' and not o.name = any (e.tables))
      or (o.kind = 'view' and not o.name = any (e.views))
      or (o.kind = 'function' and not o.name = any (e.funcs))
      or (o.kind = 'type' and not o.name = any (e.types))
      or o.kind in ('matview', 'foreign table')
),
checks as (
  select 1 as ord, 'supabase_platform' as check_name,
         case when (select count(*) from pg_namespace where nspname in ('auth', 'storage', 'extensions')) = 3
                   and to_regclass('auth.users') is not null and to_regprocedure('auth.uid()') is not null
              then 'OK' else 'REJECT' end as status,
         'auth/storage/extensions schemas, auth.users and auth.uid() must exist (this must be a Supabase project database)' as detail
  union all
  select 2, 'api_roles',
         case when (select count(*) from pg_roles where rolname in ('anon', 'authenticated', 'service_role', 'authenticator')) = 4 then 'OK' else 'REJECT' end,
         'anon, authenticated, service_role and authenticator roles must exist'
  union all
  select 3, 'target_schema',
         case when not (select present from schema_state) then 'OK'
              when to_regclass('solvant.schema_migrations') is null then 'REJECT'
              else 'INFO' end,
         case when not (select present from schema_state) then 'schema solvant does not exist yet: fresh install'
              when to_regclass('solvant.schema_migrations') is null then 'a schema named solvant exists but was NOT created by this app (no ledger): refusing to touch it'
              else 'schema solvant exists with this app''s migration ledger: re-apply / upgrade' end
  union all
  select 4, 'unexpected_objects_in_solvant',
         case when (select count(*) from unexpected) = 0 then 'OK' else 'REJECT' end,
         coalesce((select 'not created by these migrations: ' || string_agg(kind || ' ' || name, ', ' order by kind, name) from unexpected),
                  'no foreign objects in schema solvant')
  union all
  select 5, 'migration_ledger',
         case when to_regclass('solvant.schema_migrations') is null then 'OK'
              when exists (select 1 from ledger l, expected e, unnest(l.versions) v where not v = any (e.versions)) then 'REJECT'
              else 'OK' end,
         case when to_regclass('solvant.schema_migrations') is null then 'no ledger yet (fresh install)'
              else 'applied versions: ' || coalesce((select nullif(array_to_string(versions, ', '), '') from ledger), 'none')
                   || ' (unknown versions => REJECT: database is ahead of this code)' end
  union all
  select 6, 'pg_trgm_location',
         case when not exists (select 1 from pg_extension where extname = 'pg_trgm') then 'OK'
              when (select n.nspname from pg_extension x join pg_namespace n on n.oid = x.extnamespace where x.extname = 'pg_trgm') = 'extensions' then 'OK'
              else 'REJECT' end,
         coalesce((select 'pg_trgm installed in schema ' || n.nspname from pg_extension x join pg_namespace n on n.oid = x.extnamespace where x.extname = 'pg_trgm'),
                  'pg_trgm not installed: will be created in schema extensions')
  union all
  select 7, 'public_schema_untouched', 'INFO',
         'migrations create nothing in public; existing public tables (left as they are): ' ||
         (select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind in ('r', 'p', 'v'))::text
  union all
  select 8, 'data_api_exposure',
         case when exists (select 1 from pg_roles r, unnest(coalesce(r.rolconfig, '{}')) cfg
                            where r.rolname = 'authenticator' and cfg like 'pgrst.db_schemas=%' and cfg like '%solvant%') then 'OK' else 'WARN' end,
         'schema solvant must be listed under Project Settings → Data API → Exposed schemas before the app can query it'
  union all
  select 9, 'existing_lead_data',
         case when to_regclass('solvant.opportunities') is null then 'OK' else 'INFO' end,
         case when to_regclass('solvant.opportunities') is null then 'no application data present'
              else 'application tables already exist; re-applying keeps all rows (no drops, no deletes)' end
)
select ord, status, check_name, detail from checks
union all
select 0, case when exists (select 1 from checks where status = 'REJECT') then 'REJECT' else 'OK' end, 'VERDICT',
       case when exists (select 1 from checks where status = 'REJECT') then 'Do NOT apply the migrations to this database'
            else 'Safe to apply the Solvant migrations to this database (see WARN/INFO rows)' end
order by 1;

rollback;
